import{_ as e,o as t,c as r,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"录入问答和文档","description":"","frontmatter":{"title":"录入问答和文档"},"headers":[],"relativePath":"knowledge/qa-and-files.md","filePath":"knowledge/qa-and-files.md","lastUpdated":1787948622000}'),l={name:"knowledge/qa-and-files.md"};function n(i,a,s,d,h,c){return t(),r("div",null,[...a[0]||(a[0]=[o(`<h1 id="录入问答和文档" tabindex="-1">录入问答和文档 <a class="header-anchor" href="#录入问答和文档" aria-label="Permalink to &quot;录入问答和文档&quot;">​</a></h1><p>知识库的「知识项」标签页支持四种录入方式。按内容形态选合适的方式，AI 检索效果会更好。</p><h2 id="四种录入方式" tabindex="-1">四种录入方式 <a class="header-anchor" href="#四种录入方式" aria-label="Permalink to &quot;四种录入方式&quot;">​</a></h2><h3 id="问答" tabindex="-1">问答 <a class="header-anchor" href="#问答" aria-label="Permalink to &quot;问答&quot;">​</a></h3><p>一问一答的形式，最推荐的方式。问题写顾客的问法，答案写你希望 AI 参考的说法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问：多久发货？</span></span>
<span class="line"><span>答：默认 48 小时内发货，预售商品以商品页标注为准。</span></span></code></pre></div><h3 id="文本" tabindex="-1">文本 <a class="header-anchor" href="#文本" aria-label="Permalink to &quot;文本&quot;">​</a></h3><p>一段独立的说明文字，适合不成问答形式的资料，比如一段售后流程说明。</p><h3 id="markdown-文档" tabindex="-1">Markdown 文档 <a class="header-anchor" href="#markdown-文档" aria-label="Permalink to &quot;Markdown 文档&quot;">​</a></h3><p>把整篇 Markdown 文档贴进来，系统会<strong>按标题章节自动拆分</strong>成多个知识片段。适合已有成型文档的场景。也支持导入 Word / PDF 等文档资料。</p><h3 id="excel-批量导入" tabindex="-1">Excel 批量导入 <a class="header-anchor" href="#excel-批量导入" aria-label="Permalink to &quot;Excel 批量导入&quot;">​</a></h3><p>批量上传问答：Excel 每行一对问题和答案。适合把客服团队积累的话术表一次性灌进来。</p><h2 id="写好知识内容的要点" tabindex="-1">写好知识内容的要点 <a class="header-anchor" href="#写好知识内容的要点" aria-label="Permalink to &quot;写好知识内容的要点&quot;">​</a></h2><ul><li><strong>一条只讲一件事</strong>。「发货时效」和「退换政策」分成两条，别堆在一起——检索是按条命中的。</li><li><strong>问题用顾客的原话</strong>。顾客问「什么时候能到」而不是「物流时效咨询」。翻聊天记录找真实问法。</li><li><strong>答案写完整</strong>。AI 会参考答案组织语言，答案本身含糊，AI 也答不清楚。</li><li><strong>有时效的内容标注清楚</strong>。活动话术写上活动时间，过期后及时删除。</li></ul><h2 id="待审核条目" tabindex="-1">待审核条目 <a class="header-anchor" href="#待审核条目" aria-label="Permalink to &quot;待审核条目&quot;">​</a></h2><p>部分自动产生的知识项（比如 AI 从接待中整理的问答）会带<strong>待审核</strong>状态。审核确认后才会正式参与回答。收到「AI 推送待办信息」通知时，来这里处理。</p><h2 id="修改和删除" tabindex="-1">修改和删除 <a class="header-anchor" href="#修改和删除" aria-label="Permalink to &quot;修改和删除&quot;">​</a></h2><ul><li>问答、文本、文档类型的知识项可以直接编辑。</li><li>商品学习产生的商品资料不在知识项里改，去「商品」标签页维护，见<a href="/aicare-docs/knowledge/product-learn">商品学习</a>。</li><li>支持多选批量删除。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>内容录了但 AI 没答上来？</strong> 先检查库是否绑定到了当前方案，再用<a href="/aicare-docs/solution/test">对话测试</a>复现，看引用了什么资料。详细排查见<a href="/aicare-docs/faq/accuracy">回答不准怎么办</a>。</p><p><strong>知识条数有上限吗？</strong> 知识库和商品库条数不设限。</p>`,21)])])}const g=e(l,[["render",n]]);export{u as __pageData,g as default};
